const currencyTable={IN:{currency:'INR',locale:'en-IN',rate:84},US:{currency:'USD',locale:'en-US',rate:1},GB:{currency:'GBP',locale:'en-GB',rate:.79},CA:{currency:'CAD',locale:'en-CA',rate:1.36},AU:{currency:'AUD',locale:'en-AU',rate:1.52},NZ:{currency:'NZD',locale:'en-NZ',rate:1.66},AE:{currency:'AED',locale:'en-AE',rate:3.67},SG:{currency:'SGD',locale:'en-SG',rate:1.35}};function countryFromPhone(phone){const p=String(phone||'');return p.startsWith('+91')?'IN':p.startsWith('+44')?'GB':p.startsWith('+1')?'US':p.startsWith('+61')?'AU':p.startsWith('+64')?'NZ':p.startsWith('+971')?'AE':p.startsWith('+65')?'SG':'IN'}function activeCurrency(){const country=currentUser?.country||countryFromPhone(currentUser?.phone);return currencyTable[country]||currencyTable.IN}function money(x){const config=activeCurrency();return new Intl.NumberFormat(config.locale,{style:'currency',currency:config.currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(x)*config.rate)}function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}function showDeliveryPlace(label){const el=document.querySelector('#deliveryPlaceLabel');if(el)el.textContent=label;const button=document.querySelector('#deliveryPlace');if(button)button.title=label+' · click to refresh location'}async function reverseGeocodeDeliveryPlace(latitude,longitude){const endpoint=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(latitude)}&lon=${encodeURIComponent(longitude)}&zoom=14&addressdetails=1`;const response=await fetch(endpoint,{headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('Location lookup failed');const data=await response.json(),a=data.address||{},place=a.neighbourhood||a.suburb||a.city_district||a.town||a.city||a.village||a.county||a.state;if(!place)throw new Error('Area name unavailable');const region=a.city||a.town||a.state;return region&&region.toLowerCase()!==place.toLowerCase()?`${place}, ${region}`:place}function detectDeliveryLocation(manual=false){if(!navigator.geolocation){showDeliveryPlace('Location unavailable · tap to retry');if(manual)toast('This browser does not provide location access.');return}const isVendor=String(currentUser?.role||'').toLowerCase()==='vendor',label=document.querySelector('#deliveryPlaceLabel');if(label)label.textContent=isVendor?'Finding your current location…':'Finding your delivery point…';navigator.geolocation.getCurrentPosition(async position=>{try{const {latitude,longitude}=position.coords,place=await reverseGeocodeDeliveryPlace(latitude,longitude);if(isVendor){showDeliveryPlace('Your current location: '+place);currentUser.currentLocation={address:place,latitude,longitude,updatedAt:Date.now()};localStorage.setItem('currentUser',JSON.stringify(currentUser));localStorage.setItem('ng-session',JSON.stringify(currentUser))}else{showDeliveryPlace('Deliver to '+place);const point={address:place,latitude,longitude,updatedAt:Date.now(),source:'device'};if(currentUser?.id)localStorage.setItem('deliveryAddress:'+currentUser.id,JSON.stringify(point));localStorage.setItem('ng-delivery-location',JSON.stringify({label:place,updatedAt:Date.now()}))}}catch{showDeliveryPlace(isVendor?'Your current location':'Set your delivery point');if(manual)toast('Could not identify the location. Please try again.')}},error=>{showDeliveryPlace(error.code===1?(isVendor?'Allow location access to detect your current location':'Set your delivery point at checkout'):(isVendor?'Your current location':'Set your delivery point'));if(manual)toast(error.code===1?'Allow location access in your browser, or enter your delivery point at checkout.':'Could not get your location. Please try again.')},{enableHighAccuracy:false,timeout:10000,maximumAge:300000})}function initializeDeliveryLocation(){const button=document.querySelector('#deliveryPlace'),isVendor=String(currentUser?.role||'').toLowerCase()==='vendor';button?.addEventListener('click',()=>detectDeliveryLocation(true));try{if(isVendor){const saved=currentUser.currentLocation?.address;if(saved){showDeliveryPlace('Your current location: '+saved);return}showDeliveryPlace('Set your current location');return}if(currentUser?.id){const savedPoint=JSON.parse(localStorage.getItem('deliveryAddress:'+currentUser.id)||'null');if(savedPoint?.address){showDeliveryPlace('Deliver to '+savedPoint.address);return}}const saved=JSON.parse(localStorage.getItem('ng-delivery-location')||'null');if(saved?.label){showDeliveryPlace('Deliver to '+saved.label);return}}catch{}showDeliveryPlace(isVendor?'Set your current location':'Set your delivery point')}
function render(){document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#cartCount').textContent=cart.reduce((a,x)=>a+x.qty,0);if(page==='home')home();else if(page==='orders'){if(!currentUser||currentUser.role!=='Customer'){page=currentUser?.role==='Vendor'?'dashboard':'home';page==='dashboard'?dashboard():home()}else ordersPage()}else if(page==='dashboard'){if(!currentUser){page='home';home();authModal('login')}else if(currentUser.role!=='Vendor'){page='home';home()}else dashboard()}}
function popularSearchTerms(){const owned=currentUser&&currentUser.role==='Customer'?orders.filter(o=>o.customerEmail===currentUser.email):[];const source=owned.length?owned:orders;const counts=new Map(products.map(p=>[p.name,0]));for(const order of source){if(Array.isArray(order.itemsList)){for(const item of order.itemsList)if(counts.has(item.name))counts.set(item.name,counts.get(item.name)+Number(item.qty||1));continue}for(const part of String(order.items||'').split(',')){const text=part.trim(),match=text.match(/^([0-9]+)\\s*[×x]\\s*(.+)$/i),name=match?match[2].trim():text;if(counts.has(name))counts.set(name,counts.get(name)+(match?Number(match[1]):1))}}return [...products].sort((a,b)=>counts.get(b.name)-counts.get(a.name)||products.indexOf(a)-products.indexOf(b)).slice(0,5).map(p=>p.name)}function popularSearchTerm(){const choices=popularSearchTerms();return choices[searchSuggestionIndex%choices.length]||'local produce'}
